/* Prix d'une obligation à coupon annuel en fonction du rendement */
(function () {
  var svg = document.getElementById("ob-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }
  function price(c,T,y){ var P=0; for(var t=1;t<=T;t++){ var cf=(t<T)?c:(c+100); P+=cf/Math.pow(1+y,t); } return P; }

  function draw(){
    var c=v("ob-c"), T=Math.round(v("ob-t")), y=v("ob-y")/100;
    setT("ob-c-o", c.toFixed(2)+"%"); setT("ob-t-o", T); setT("ob-y-o",(y*100).toFixed(2)+"%");
    var P=price(c,T,y);
    setT("ob-price", P.toFixed(2));
    var st = Math.abs(P-100)<0.05 ? (al()==="en"?"at par":(al()==="nl"?"à pari":"au pair"))
           : (P>100 ? (al()==="en"?"premium":(al()==="nl"?"premie":"prime")) : (al()==="en"?"discount":(al()==="nl"?"disagio":"décote")));
    setT("ob-status", st);
    setT("ob-cy", c>0 ? (c/P*100).toFixed(2)+"%" : "—");

    var W=520,H=260,L=42,R=14,T2=14,B=32, pw=W-L-R, ph=H-T2-B;
    var ymin=0.01, ymax=0.10;
    var N=90, xs=[], pv=[];
    for (var i=0;i<=N;i++){ var yy=ymin+(ymax-ymin)*i/N; xs.push(yy); pv.push(price(c,T,yy)); }
    var pmin=Infinity,pmax=-Infinity; for (var j=0;j<=N;j++){ pmin=Math.min(pmin,pv[j]); pmax=Math.max(pmax,pv[j]); }
    pmin=Math.min(pmin,100); pmax=Math.max(pmax,100); var pad=(pmax-pmin)*0.08; pmin-=pad; pmax+=pad;
    function px(yy){ return L + (yy-ymin)/(ymax-ymin)*pw; }
    function py(pp){ return T2 + (1-(pp-pmin)/(pmax-pmin))*ph; }

    var g="";
    g+='<line class="axis" x1="'+L+'" y1="'+T2+'" x2="'+L+'" y2="'+(T2+ph)+'"/>';
    g+='<line class="axis" x1="'+L+'" y1="'+(T2+ph)+'" x2="'+(L+pw)+'" y2="'+(T2+ph)+'"/>';
    // ligne pair = 100
    g+='<line x1="'+L+'" y1="'+py(100).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(100).toFixed(1)+'" stroke="var(--ink-mute)" stroke-width="1" stroke-dasharray="2 3"/>';
    g+='<text class="tick" x="'+(L+pw)+'" y="'+(py(100)-3).toFixed(1)+'" text-anchor="end">100</text>';
    // courbe prix-taux
    var tp="M "+px(xs[0]).toFixed(1)+","+py(pv[0]).toFixed(1);
    for (var k=1;k<=N;k++) tp+=" L "+px(xs[k]).toFixed(1)+","+py(pv[k]).toFixed(1);
    g+='<path d="'+tp+'" fill="none" stroke="var(--teal)" stroke-width="2.6"/>';
    // point courant
    g+='<circle cx="'+px(y).toFixed(1)+'" cy="'+py(P).toFixed(1)+'" r="4" fill="var(--ink)"/>';
    g+='<line class="axis" x1="'+px(y).toFixed(1)+'" y1="'+py(P).toFixed(1)+'" x2="'+px(y).toFixed(1)+'" y2="'+(T2+ph)+'" stroke-dasharray="3 3" stroke-width="1"/>';
    // ticks
    g+='<text class="tick" x="'+L+'" y="'+(H-16)+'" text-anchor="start">1%</text>';
    g+='<text class="tick" x="'+px(y).toFixed(1)+'" y="'+(H-16)+'" text-anchor="middle">'+(y*100).toFixed(1)+'%</text>';
    g+='<text class="tick" x="'+(L+pw)+'" y="'+(H-16)+'" text-anchor="end">10%</text>';
    g+='<text class="tick" x="'+(L-6)+'" y="'+(py(pmax)+4).toFixed(1)+'" text-anchor="end">'+pmax.toFixed(0)+'</text>';
    g+='<text class="tick" x="'+(L-6)+'" y="'+(py(pmin)+4).toFixed(1)+'" text-anchor="end">'+pmin.toFixed(0)+'</text>';
    var xlab = al()==="en"?"market yield":(al()==="nl"?"marktrendement":"rendement de marché");
    var ylab = al()==="en"?"price":(al()==="nl"?"prijs":"prix");
    g+='<text class="lab" x="'+(L+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">'+xlab+'</text>';
    g+='<text class="lab" x="'+(L-32)+'" y="'+(T2+ph/2)+'" text-anchor="middle" transform="rotate(-90 '+(L-32)+' '+(T2+ph/2)+')">'+ylab+'</text>';
    svg.innerHTML=g;
  }

  ["ob-c","ob-t","ob-y"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
